from collections.abc import Iterable
from itertools import islice, zip_longest


def zip_offset(*iterables, offsets, longest=False, fillvalue=None):
    """``zip`` the input *iterables* together, but offset the `i`-th iterable
    by the `i`-th item in *offsets*.

        >>> list(zip_offset('0123', 'abcdef', offsets=(0, 1)))
        [('0', 'b'), ('1', 'c'), ('2', 'd'), ('3', 'e')]

    This can be used as a lightweight alternative to SciPy or pandas to analyze
    data sets in which some series have a lead or lag relationship.

    By default, the sequence will end when the shortest iterable is exhausted.
    To continue until the longest iterable is exhausted, set *longest* to
    ``True``.

        >>> list(zip_offset('0123', 'abcdef', offsets=(0, 1), longest=True))
        [('0', 'b'), ('1', 'c'), ('2', 'd'), ('3', 'e'), (None, 'f')]

    By default, ``None`` will be used to replace offsets beyond the end of the
    sequence. Specify *fillvalue* to use some other value.

    """
    if not isinstance(offsets, Iterable) or isinstance(offsets, (str, bytes)):
        raise TypeError('offsets must be an iterable of non-negative integers')
    offsets = tuple(offsets)

    if not isinstance(longest, bool):
        raise TypeError('longest must be a bool')

    for iterable in iterables:
        if not isinstance(iterable, Iterable):
            raise TypeError('every positional argument must be iterable')

    if len(offsets) != len(iterables):
        raise ValueError('offsets must have one item per iterable')

    for offset in offsets:
        if isinstance(offset, bool) or not isinstance(offset, int):
            raise TypeError('each offset must be an int')
        if offset < 0:
            raise ValueError('each offset must be non-negative')

    shifted = [
        islice(iter(iterable), offset, None)
        for iterable, offset in zip(iterables, offsets)
    ]

    if longest:
        return zip_longest(*shifted, fillvalue=fillvalue)
    return zip(*shifted)
